import{hasImmediateSafetyRisk}from"./monster-brain-v3.js";
import*as DB from"./db.js";
import{GameAudio}from"./audio-manager.js";
import{PixelFX}from"./pixel-fx.js";
import{EncounterDirector}from"./v4/encounter-director.js";
import{CombatEngine}from"./v4/combat-engine.js";
import{ArenaView}from"./v4/arena-generator.js";
import{DialogueDirector}from"./v4/dialogue-director.js";
import{StoryDirector}from"./v4/story-director.js";
import{renderMonster,updateMonster}from"./v4/monster-renderer.js";
import{AttractMode}from"./v4/attract-mode.js";
import{WeaponDirector,WEAPONS}from"./v4/weapon-director.js";
import{CameraDirector}from"./v4/camera-director.js";
import{todaysChaos}from"./v4/mutation-engine.js";
import{escapeHTML}from"./v4/utils.js";

const $=id=>document.getElementById(id),audio=new GameAudio(),director=new EncounterDirector(DB),state={inputMode:"emotion",generationMode:"offline",encounter:null,combat:null,arena:null,fx:null,monster:null,dialogue:null,story:null,weapon:null,camera:null,chaosTimer:null,startedAt:0,aiContext:null,nemesis:null,timers:new Set(),sound:true,saveRaw:false,finishing:false};
const views=["homeView","inputView","battleView","dexView","safetyView"];
const palette=()=>{const v=state.encounter?.monsterDNA.visual;return v?[v.primaryColor,v.secondaryColor,v.accentColor]:["#ff4f78","#a56cff","#ffd84d"]};
const later=(fn,ms)=>{const id=setTimeout(()=>{state.timers.delete(id);fn()},ms);state.timers.add(id);return id};
const toast=text=>{const el=$("toast");el.textContent=text;el.classList.add("show");later(()=>el.classList.remove("show"),1900)};
function show(id){for(const v of views)$(v)?.classList.toggle("active",v===id);document.body.dataset.view=id;document.documentElement.dataset.view=id;if(id==="homeView")attract.start();else attract.stop()}
function banner(text,tone=""){const el=$("combatBanner");el.textContent=text;el.dataset.tone=tone;el.classList.remove("show");void el.offsetWidth;el.classList.add("show");later(()=>el.classList.remove("show"),1300)}
function speech(text,kind="full"){const el=$("speechBubble");el.textContent=text;el.dataset.kind=kind;el.classList.add("show");later(()=>el.classList.remove("show"),kind==="grunt"?650:2300)}
function vibrate(pattern){if(navigator.vibrate)navigator.vibrate(pattern)}
function formatTime(ms){const s=Math.max(0,Math.floor(ms/1000));return`${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`}
function setDirectorMode(mode,persist=true){state.generationMode=mode;document.querySelectorAll("[data-director]").forEach(x=>x.classList.toggle("active",x.dataset.director===mode));const label=$("directorPrivacy");if(label)label.textContent=mode==="offline"?"全程离线 · 免费 · 原文默认不保存":"先查本地 AI 怪物库 · 仅缺少匹配时请你手动调用 ChatGPT 一次";if(persist)DB.setSetting("generationMode",mode)}
function chooseMode(mode){state.inputMode=mode;$("modeBadge").textContent=mode==="emotion"?"脑内作战":"人间奇葩";$("promptTitle").textContent=mode==="emotion"?"现在什么东西在折磨你？":"那个人做了什么让你不爽？";$("ventInput").placeholder=mode==="emotion"?"随便说，不用组织语言，也不用文明……":"描述行为就行，不需要写真名……";document.body.dataset.enter=mode;show("inputView");$("ventInput").focus();later(()=>delete document.body.dataset.enter,mode==="emotion"?420:520)}
function cleanupBattle(returnMenu=true){for(const id of state.timers)clearTimeout(id);state.timers.clear();clearTimeout(state.chaosTimer);state.chaosTimer=null;state.dialogue?.destroy();state.story?.destroy();state.weapon?.destroy();state.camera?.destroy();state.fx?.destroy();state.arena?.destroy();state.combat?.destroy();audio.stopWeapon();state.dialogue=state.story=state.weapon=state.camera=state.fx=state.arena=state.combat=state.monster=null;state.encounter=null;state.finishing=false;$("arena").replaceChildren();$("battleEnd").classList.remove("show");$("finisherPanel").classList.remove("show");$("releaseHud")?.classList.remove("show","full");$("weaponStatus")?.classList.remove("show");document.body.classList.remove("rage-mode","release-mode","silence-mode");audio.releaseBattle(returnMenu);diagnostics()}

const errorText=error=>({AI_LIBRARY_ERROR:"AI怪物库读取失败。",AI_IMPORT_ERROR:"AI JSON 导入失败，请检查格式和缺失字段。",ENCOUNTER_RENDER_ERROR:"战斗场景加载失败，请再试一次。",STORAGE_ERROR:"本地存储出了点问题，请检查浏览器空间。",UNKNOWN_ERROR:"这一局出了点问题，再试一次。"}[error?.code||"UNKNOWN_ERROR"]);
async function begin(){const text=$("ventInput").value.trim();if(!text)return;if(hasImmediateSafetyRisk(text)){show("safetyView");return}await audio.unlock();$("releaseBtn").disabled=true;$("releaseBtn").classList.add("loading");try{const result=await director.create(text,state.inputMode,state.generationMode);if(result.status==="needs-ai"){state.aiContext=result;$("aiPrompt").value=result.prompt;$("aiJson").value="";$("aiError").textContent="";$("aiBridgeDialog").showModal();return}await launch(result.encounter,text,result)}catch(error){console.error(error);toast(errorText(error))}finally{$("releaseBtn").disabled=false;$("releaseBtn").classList.remove("loading")}}
async function launch(encounter,raw,result={}){cleanupBattle(false);state.encounter=encounter;state.combat=new CombatEngine(encounter);state.startedAt=performance.now();const key=encounter.semanticDNA.concepts.join("+")||encounter.semanticDNA.label;let recent=[];try{state.nemesis=await DB.upsertNemesis(key,{monsterId:encounter.monsterDNA.id,name:encounter.monsterDNA.name,mutations:encounter.mutationDNA.map(x=>x.id),combat:encounter.combatDNA.behaviors,personality:encounter.monsterDNA.personality,arena:encounter.arenaDNA.theme,origin:encounter.origin});recent=await DB.getRecentEncounters(8);await DB.saveEncounterV4(encounter,{status:"started",raw:state.saveRaw?raw:undefined,reused:Boolean(result.reused),crossover:Boolean(result.crossover)})}catch(cause){cleanupBattle(false);const error=Error("storage");error.code="STORAGE_ERROR";error.cause=cause;throw error}if(state.nemesis.generation>=3){encounter.monsterDNA.rarity="NEMESIS";encounter.dialogueDNA.intro=[...(encounter.dialogueDNA.nemesis||[]),...encounter.dialogueDNA.intro]}
  try{show("battleView");$("battleEnd").classList.remove("show");$("finisherPanel").classList.remove("show");$("enemyName").textContent=encounter.monsterDNA.name;$("enemyRarity").textContent=encounter.monsterDNA.rarity;$("mutationBadge").textContent=encounter.mutationDNA.length?`? MUTATION × ${encounter.mutationDNA.length}`:"CLASSIC";$("mutationBadge").classList.toggle("hidden-mod",encounter.mutationDNA.length>0);$("phaseLabel").textContent="DEFIANT";$("styleRank").textContent="C";renderArmor();updateHud();
  const root=$("arena");state.arena=new ArenaView(root,encounter.arenaDNA,prop=>attack("weapon",{wall:true,arenaChanged:true,propType:prop.type,vector:{x:1,y:0},charge:1}));state.monster=renderMonster(root,encounter,state.combat);state.fx=new PixelFX(root);state.camera=new CameraDirector($("battleView"),root);const recentWeapons=recent.flatMap(x=>x.summary?.weapons||[]);state.weapon=new WeaponDirector(root,encounter,recentWeapons,{onDrop:w=>{banner(`WEAPON DROP · ${w.label}`,"weapon");audio.weapon(w.id,"drop")},onEquip:(w,n)=>weaponStatus(w,n),onStart:w=>audio.startWeapon(w.id),onStop:()=>audio.stopWeapon(),onImpact:(w,ctx)=>weaponAttack(w,ctx),onUse:(w,n)=>weaponStatus(w,n),onBreak:w=>{audio.stopWeapon();audio.weapon(w.id,"break");banner(`${w.label} 笑着报废了`,"break");$("weaponStatus").classList.remove("show")}});state.dialogue=new DialogueDirector(encounter.dialogueDNA,{speak:(t,k)=>speech(t,k),grunt:t=>speech(t,"grunt")});state.story=new StoryDirector(encounter.storyDNA,event=>{if(event.core)banner(`核心暴露：${event.core}`,"core");else if(event.beat==="armor-break")banner(`象征外壳破裂：${event.data.label}`,"armor")});state.story.beat("intro");state.dialogue.start();attachGestures(state.monster);audio.startBattle(encounter.monsterDNA.rarity==="BOSS"||encounter.monsterDNA.rarity==="NEMESIS");audio.setCombatLayer("base");startPersonality();later(()=>state.weapon?.drop("arrival"),1100);later(()=>$("mutationBadge")?.classList.add("hud-faded"),4200);startChaos();diagnostics()}catch(cause){cleanupBattle(false);const error=Error("render");error.code="ENCOUNTER_RENDER_ERROR";error.cause=cause;throw error}}
function renderArmor(){const box=$("armorHud"),armor=state.combat?.armor||[];box.innerHTML=armor.map(x=>`<span class="armor-chip ${x.state}" title="${escapeHTML(x.label)}">${x.state==="broken"?"◇":"◆"} ${escapeHTML(x.label)}</span>`).join("")}
function weaponStatus(w,remaining){const el=$("weaponStatus");if(!el)return;el.innerHTML=`<strong>${escapeHTML(w.label)}</strong><span>${escapeHTML(w.input)} · ${remaining} USE</span>`;el.dataset.weapon=w.id;el.classList.add("show")}
function weaponAttack(w,context={}){if(!state.monster)return;state.monster.dataset.reaction=w.reaction;state.monster.classList.remove("weapon-react");void state.monster.offsetWidth;state.monster.classList.add("weapon-react");later(()=>{state.monster?.classList.remove("weapon-react");if(state.monster)delete state.monster.dataset.reaction},Math.max(360,w.hitStop*5));state.arena?.interact(w.interaction,w.damage>25?2:1);state.camera?.impact(w.id,context?.point?.x||0);audio.weapon(w.id);vibrate(w.haptic);attack("weapon",{...context,weaponId:w.id,weaponDamage:w.damage,weaponHitStop:w.hitStop,weaponRelease:w.release,charge:Math.max(.5,context.charge||.7),arenaChanged:true,wall:["spring","blower"].includes(w.id)})}
function startChaos(){const run=()=>{if(!state.combat||state.finishing)return;const kinds=["bin-roll","chandelier-drop","vending-spit"],kind=state.arena?.chaos(kinds[Math.floor(Math.random()*kinds.length)]);if(kind){banner({"bin-roll":"垃圾桶越狱了","chandelier-drop":"吊灯决定参战","vending-spit":"售货机吐槽三连"}[kind],"chaos");if(kind==="chandelier-drop")state.arena.hit({power:1,targetX:50})}state.chaosTimer=later(run,3000+Math.random()*5000)};state.chaosTimer=later(run,3200+Math.random()*2800)}
function updateHud(){if(!state.combat)return;const c=state.combat,p=Math.max(0,c.hp/c.maxHp*100);$("hpFill").style.width=`${p}%`;$("hpText").textContent=c.mode==="battle"?`${c.hp} / ${c.maxHp}`:"BROKEN";$("comboCount").textContent=c.combo;$("enemyPhase").textContent=c.phase;$("phaseLabel").textContent=c.mode==="release"?(c.fullRelease?"FULL RELEASE":"RELEASE"):c.phase;$("styleRank").textContent=c.style();document.documentElement.dataset.combatMode=c.mode;document.documentElement.dataset.phase=c.phase;document.documentElement.dataset.style=c.style();if(c.mode==="release"){const hud=$("releaseHud");hud.classList.add("show");hud.classList.toggle("full",c.fullRelease);$("releaseFill").style.width=`${c.release}%`;$("releaseText").textContent=c.fullRelease?"FULL RELEASE":`释放 ${Math.round(c.release)}%`;const tick=c.tick();$("finishNowBtn").disabled=!tick.canFinish;$("finishNowBtn").textContent=tick.canFinish?"选择终结技":"继续打它…"}}
function revealMutations(){const badge=$("mutationBadge");if(!badge.classList.contains("hidden-mod"))return;badge.classList.remove("hidden-mod");badge.textContent=state.encounter.mutationDNA.map(x=>x.label).join(" × ");banner(`变异规则：${badge.textContent}`,"mutation")}
function attack(type,context={}){if(!state.combat||state.finishing)return;const rootRect=$("arena").getBoundingClientRect(),rect=state.monster.getBoundingClientRect(),targetX=((rect.x+rect.width/2-rootRect.x)/rootRect.width)*100,wall=context.wall??(targetX<18||targetX>82||Math.abs(context.vector?.x||0)>.85),arenaHit=type!=="punch"||state.combat.combo%4===0?state.arena.hit({power:type==="heavy"||type==="slam"?2:1,wall,targetX}):null,event=state.combat.attack(type,{...context,wall,arenaChanged:context.arenaChanged||arenaHit?.changed,propType:context.propType||arenaHit?.prop?.type});if(event.ignored)return;revealMutations();state.monster.classList.remove("hit-snap","hit-whip","hit-lift","hit-ground","hit-throw","hit-spin","hit-slow","hit-rush","hit-weapon");void state.monster.offsetWidth;state.monster.classList.add(`hit-${event.config.identity}`);$("battleView").classList.add("hit-stop");later(()=>$("battleView").classList.remove("hit-stop"),event.config.hitStop);state.camera?.impact(type,context.vector?.x||0);state.fx.hit(rect,palette(),event.config.power);if(arenaHit?.changed)state.fx.debris(rect,palette(),event.config.power);audio.play(type,{gain:.7+event.config.power*.25,rate:.94+Math.random()*.12});if(wall)audio.play("wall",{gain:.72});vibrate(event.critical?[18,20,28]:event.config.power>.8?[22,12,18]:10);updateMonster(state.monster,state.encounter,state.combat);state.dialogue.hit(event);updateHud();renderArmor();if(event.critical)banner("CRITICAL!","critical");if(event.secret){DB.addDiscovery(event.secret,"secret",{ "mirror-slap":"镜像巴掌","wall-echo":"墙壁回声","rage-crater":"怒气陨坑","return-the-credit":"把奖杯还回去"}[event.secret]||event.secret);state.dialogue.special();banner("SECRET DISCOVERED","secret")}
  if(event.armorBroken){state.story.beat("armor-break",{label:event.armorBroken.label});audio.play("critical",{gain:.86});state.weapon?.drop("armor break")}if(event.phaseChanged){state.arena?.setStage(event.phase);state.dialogue.setStage(event.phase);state.story.beat(event.phase.toLowerCase());banner(event.phase,event.phase.toLowerCase());audio.setCombatLayer(event.phase==="CRACKED"?"percussion":"rage")}if(event.combo===10||event.combo===20||event.combo===30){banner(event.combo===30?"RAGE × 30":`${event.combo} HIT`,"combo");audio.combo(event.combo);if(event.combo===20)state.weapon?.drop("combo");if(event.combo===30){document.body.classList.add("rage-mode");audio.setCombatLayer("rage")}}if(event.break)enterRelease();if(event.fullRelease){state.arena?.setStage("full");state.camera?.release(true);state.fx.releasePulse(rect,palette(),true);banner("FULL RELEASE · 你决定何时结束","full");audio.setCombatLayer("full")}diagnostics()}
function enterRelease(){document.body.classList.add("release-mode");$("hpFill").style.width="0%";state.arena.setStage("release");state.weapon?.releaseMode();state.camera?.release(false);state.fx.releasePulse(state.monster.getBoundingClientRect(),palette());state.story.beat("break");state.dialogue.setStage("breakdown");state.dialogue.ko();banner("BREAK! 继续打，结束由你决定。","break");audio.setCombatLayer("break");later(()=>audio.setCombatLayer("release"),700);const tick=()=>{if(!state.combat||state.combat.mode!=="release")return;updateHud();later(tick,200)};tick()}
function attachGestures(el){let start=null;el.addEventListener("pointerdown",e=>{if(!["battle","release"].includes(state.combat?.mode))return;const point={x:e.clientX,y:e.clientY};if(state.weapon?.pointerDown(point)){start={weapon:true,id:e.pointerId};el.setPointerCapture?.(e.pointerId);return}start={x:e.clientX,y:e.clientY,t:performance.now(),id:e.pointerId};el.setPointerCapture?.(e.pointerId);el.classList.add("charging")});el.addEventListener("pointermove",e=>{if(start?.weapon)state.weapon?.pointerMove({x:e.clientX,y:e.clientY})});el.addEventListener("pointerup",e=>{if(!start)return;if(start.weapon){state.weapon?.pointerUp({x:e.clientX,y:e.clientY});start=null;return}el.classList.remove("charging");const dx=e.clientX-start.x,dy=e.clientY-start.y,dt=performance.now()-start.t,d=Math.hypot(dx,dy),charge=Math.min(1,dt/900),vector={x:Math.sign(dx),y:Math.sign(dy)};let type="punch";if(dt>470&&d<38)type="heavy";else if(d>82&&Math.abs(dx)>Math.abs(dy)*1.25)type="slap";else if(d>72&&dy<-35)type="uppercut";else if(d>72&&dy>35)type="smash";else if(d>42&&Math.abs(dx)>28&&Math.abs(dy)>28)type="spin";attack(type,{charge,vector});start=null});el.addEventListener("pointercancel",()=>{audio.stopWeapon();state.weapon?.pointerUp({x:0,y:0});start=null;el.classList.remove("charging")})}
function startPersonality(){const loop=()=>{if(!state.combat||state.combat.finished)return;const behaviors=state.encounter.combatDNA.behaviors||[],move=behaviors[Math.floor(Math.random()*Math.max(1,behaviors.length))]||"挑衅";state.monster.dataset.behavior=move;state.monster.classList.add("personality-move");later(()=>state.monster?.classList.remove("personality-move"),700);later(loop,2300+Math.random()*2400)};later(loop,2600)}
function showFinishers(){if(!state.combat?.canFinish)return;const choices=[["crush","delete","重力压扁 × 像素粉碎"],["void","delete","虚空吸走 × 数据消散"],["launch","crush","升空放逐 × 场景坍塌"]];$("finisherChoices").innerHTML=choices.map(x=>`<button data-finish="${x[0]},${x[1]}"><strong>${x[2]}</strong><small>结合 ${escapeHTML(state.encounter.arenaDNA.theme)} 场景</small></button>`).join("");$("finisherPanel").classList.add("show")}
async function finish(types){if(!state.combat?.finish())return;state.finishing=true;$("finisherPanel").classList.remove("show");state.dialogue.destroy();state.story.beat("finish");const rect=state.monster.getBoundingClientRect();banner("FINISH!","finish");audio.enterFinisher();state.monster.classList.add("finishing");state.arena.ruin();await Promise.all([state.fx.finisherCombo(types,rect,palette()),audio.finish()]);state.monster.classList.add("destroyed");await audio.silence(700);document.body.classList.add("silence-mode");await new Promise(r=>setTimeout(r,700));await completeResult(types.join("+"))}
async function completeResult(finisher){const c=state.combat.snapshot(),weapons=state.weapon?.stats().used||[],key=state.encounter.semanticDNA.concepts.join("+")||state.encounter.semanticDNA.label;await DB.saveEncounterV4(state.encounter,{status:"defeated",finisher,time:performance.now()-state.startedAt,maxCombo:c.maxCombo,damage:c.totalDamage,release:c.release,style:c.style,destroyedProps:state.arena.destroyed,secrets:c.secrets,weapons});await DB.upsertNemesis(key,{countEncounter:false,defeated:true,finisher,scars:[c.fullRelease?"完全释放裂痕":"终结裂痕"],name:state.encounter.monsterDNA.name});for(const m of state.encounter.mutationDNA)await DB.addDiscovery(`mutation-${m.id}`,"mutation",m.label);$("resultMonster").textContent=state.encounter.monsterDNA.name;$("resultTime").textContent=formatTime(performance.now()-state.startedAt);$("resultCombo").textContent=`${c.maxCombo} HIT`;$("resultDamage").textContent=c.totalDamage;$("resultStyle").textContent=c.style;$("resultRelease").textContent=`${Math.round(c.release)}%`;$("resultArena").textContent=`${state.arena.destroyed} 件`;$("battleEnd").classList.add("show");audio.victory();diagnostics()}

async function renderDex(tab="history"){document.querySelectorAll("[data-dex-tab]").forEach(x=>x.classList.toggle("active",x.dataset.dexTab===tab));const list=$("dexList");let rows=[];if(tab==="ai")rows=(await DB.getAIAssets()).map(x=>({name:x.monsterName,meta:`AI 怪物 · 复用 ${x.timesReused||0} 次`,body:(x.semanticCore||[]).join(" / ")}));else if(tab==="nemesis")rows=(await DB.getNemeses()).map(x=>({name:x.name||x.semanticKey,meta:`宿敌第 ${x.generation} 代 · 击败 ${x.defeatCount||0} 次`,body:(x.visualScars||[]).join(" · ")||"还在进化"}));else if(tab==="discoveries")rows=(await DB.getDiscoveries()).map(x=>({name:x.label,meta:`${x.type} · 发现 ${x.count} 次`,body:new Date(x.lastSeen).toLocaleDateString()}));else rows=(await DB.getRecentEncounters(50)).map(x=>({name:x.monsterName,meta:`${x.origin} · ${x.summary?.style||x.arena||"未结束"}`,body:new Date(x.createdAt).toLocaleString()}));list.innerHTML=rows.map(x=>`<article class="dex-card"><strong>${escapeHTML(x.name||"未命名")}</strong><small>${escapeHTML(x.meta||"")}</small><p>${escapeHTML(x.body||"")}</p></article>`).join("");$("dexEmpty").classList.toggle("show",!rows.length);$("dexStats").textContent=`${rows.length} 条本地记录`}
function diagnostics(){const c=state.combat?.snapshot();window.__monsterGameDiagnostics={version:"4.1.0",generationMode:state.generationMode,encounter:state.encounter?.id||null,combat:c||null,audio:audio.stats(),arena:state.arena?{signature:state.arena.signature(),destroyed:state.arena.destroyed}:null,weapon:state.weapon?.stats()||null};document.documentElement.dataset.release=String(c?.release||0);document.documentElement.dataset.liveCanvas=String(document.querySelectorAll("canvas").length)}

const attract=new AttractMode($("homeView"));window.__v41QA={fireAttract:id=>attract.fire(id),errorText,forceWeapon:id=>{if(!state.weapon||!WEAPONS[id])return false;state.weapon.available.unshift(WEAPONS[id]);state.weapon.drop("qa");return true}};
document.querySelectorAll("[data-mode]").forEach(x=>x.addEventListener("click",()=>chooseMode(x.dataset.mode)));
document.querySelectorAll("[data-director]").forEach(x=>x.addEventListener("click",()=>setDirectorMode(x.dataset.director)));
document.querySelectorAll("[data-back]").forEach(x=>x.addEventListener("click",()=>{if(document.body.dataset.view==="battleView")cleanupBattle();show("homeView")}));
$("homeBtn").addEventListener("click",()=>{if(document.body.dataset.view==="battleView")cleanupBattle();show("homeView")});
$("ventInput").addEventListener("input",e=>{$("charCount").textContent=`${e.target.value.length} / 280`;$("releaseBtn").disabled=!e.target.value.trim()});
document.querySelectorAll("#exampleChips button").forEach(x=>x.addEventListener("click",()=>{$("ventInput").value=x.textContent;$("ventInput").dispatchEvent(new Event("input"))}));
$("releaseBtn").addEventListener("click",begin);$("finishNowBtn").addEventListener("click",showFinishers);$("finisherChoices").addEventListener("click",e=>{const b=e.target.closest("[data-finish]");if(b)finish(b.dataset.finish.split(","))});
$("againBtn").addEventListener("click",()=>{cleanupBattle(false);chooseMode(state.inputMode)});$("endHomeBtn").addEventListener("click",()=>{cleanupBattle();show("homeView")});$("safetyHomeBtn").addEventListener("click",()=>show("homeView"));
$("dexBtn").addEventListener("click",()=>{show("dexView");renderDex()});$("homeDexBtn").addEventListener("click",()=>{show("dexView");renderDex()});document.querySelectorAll("[data-dex-tab]").forEach(x=>x.addEventListener("click",()=>renderDex(x.dataset.dexTab)));
$("homeSettingsBtn").addEventListener("click",()=>$("settingsDialog").showModal());$("saveRawToggle").addEventListener("change",e=>{state.saveRaw=e.target.checked;DB.setSetting("saveRaw",state.saveRaw)});$("menuSoundToggle").addEventListener("change",e=>{state.sound=e.target.checked;audio.setEnabled(state.sound);DB.setSetting("sound",state.sound)});$("soundBtn").addEventListener("click",()=>{$("menuSoundToggle").checked=!state.sound;$("menuSoundToggle").dispatchEvent(new Event("change"));$("soundBtn").setAttribute("aria-pressed",String(!state.sound))});
$("clearDataBtn").addEventListener("click",()=>$("confirmDialog").showModal());$("confirmClearBtn").addEventListener("click",async()=>{await DB.clearAllData();toast("本地数据已清空");renderDex()});
$("copyPromptBtn").addEventListener("click",async()=>{await navigator.clipboard.writeText($("aiPrompt").value);toast("提示词已复制")});$("aiOfflineBtn").addEventListener("click",async()=>{try{$("aiBridgeDialog").close();setDirectorMode("offline");const text=$("ventInput").value.trim(),r=await director.create(text,state.inputMode,"offline");await launch(r.encounter,text,r)}catch(error){toast(errorText(error))}});$("aiImportBtn").addEventListener("click",async()=>{try{const r=await director.importAI($("aiJson").value,state.aiContext);if(!r.ok){$("aiError").textContent=r.code==="STORAGE_ERROR"?errorText(r):r.errors.join("；");return}$("aiBridgeDialog").close();await launch(r.encounter,state.aiContext.text,{aiNew:true})}catch(error){$("aiError").textContent=errorText(error)}});
$("installBtn").addEventListener("click",async()=>{if(window.deferredInstall){window.deferredInstall.prompt();await window.deferredInstall.userChoice;window.deferredInstall=null;$("installBtn").classList.add("hidden")}});addEventListener("beforeinstallprompt",e=>{e.preventDefault();window.deferredInstall=e;$("installBtn").classList.remove("hidden")});
addEventListener("pagehide",()=>{attract.stop();if(state.encounter)cleanupBattle(false)});if("serviceWorker"in navigator)addEventListener("load",()=>navigator.serviceWorker.register("./sw.js"));
Promise.all([DB.getSetting("generationMode","offline"),DB.getSetting("sound",true),DB.getSetting("saveRaw",false)]).then(([mode,sound,save])=>{setDirectorMode(mode,false);state.sound=sound;state.saveRaw=save;$("menuSoundToggle").checked=sound;$("saveRawToggle").checked=save;audio.setEnabled(sound)});$("todayChaos").textContent=todaysChaos().label;show("homeView");diagnostics();
